import {
    BooleanColumn,
    ChoiceColumn,
    GenericColumn,
    IntegerColumn,
    ReferenceColumn,
    StringColumn,
    Table,
    TranslatedFieldColumn,
    TranslatedTextColumn,
} from '../../../db'

export const sys_atf_step_config = Table({
    name: 'sys_atf_step_config',
    extends: 'sys_metadata',
    schema: {
        active: BooleanColumn({ mandatory: false, label: 'Active', read_only: false, active: true, default: true }),
        batch_order_constraint: ChoiceColumn({
            choices: {
                stop: { label: 'Stop a batch execution', sequence: 2, inactive: false, language: 'en' },
                start: { label: 'Start a batch execution', sequence: 0, inactive: false, language: 'en' },
                middle: {
                    label: 'Run in the middle of a batch execution',
                    sequence: 1,
                    inactive: false,
                    language: 'en',
                },
            },
            dropdown: 'dropdown_with_none',
            mandatory: false,
            label: 'Batch order constraint',
            read_only: false,
            active: true,
        }),
        can_mutate_page: BooleanColumn({
            mandatory: false,
            label: 'Can mutate page',
            read_only: false,
            active: true,
            default: false,
        }),
        category: ReferenceColumn({
            mandatory: false,
            label: 'Category',
            read_only: false,
            active: true,
            referenceTable: 'sys_atf_step_config_category',
        }),
        class_name: StringColumn({
            mandatory: false,
            label: 'Class Name',
            read_only: false,
            active: true,
            maxLength: 200,
            dropdown: 'none',
        }),
        class_type: StringColumn({
            mandatory: false,
            label: 'Class type',
            read_only: false,
            active: true,
            default: 'script',
            maxLength: 40,
            dropdown: 'dropdown_without_none',
            choices: {
                java: { label: 'Java', inactive: false, language: 'en' },
                script: { label: 'Script', inactive: false, language: 'en' },
            },
        }),
        deprecated: BooleanColumn({
            mandatory: false,
            label: 'Deprecated',
            read_only: false,
            active: true,
            default: false,
        }),
        description_generator: GenericColumn({
            mandatory: false,
            label: 'Description generation script',
            read_only: false,
            active: true,
            column_type: 'script_plain',
        }),
        html_description: GenericColumn({
            mandatory: true,
            label: 'HTML description',
            read_only: false,
            active: true,
            column_type: 'translated_html',
        }),
        icon: StringColumn({
            mandatory: false,
            label: 'Icon',
            read_only: false,
            active: true,
            default: 'icon-article-document',
            maxLength: 100,
            dropdown: 'none',
        }),
        inputs: GenericColumn({
            mandatory: false,
            label: 'Input variables',
            read_only: false,
            active: true,
            column_type: 'glide_var',
        }),
        name: TranslatedFieldColumn({ mandatory: true, label: 'Name', read_only: false, active: true }),
        order: IntegerColumn({ mandatory: true, label: 'Order', read_only: false, active: true }),
        outputs: GenericColumn({
            mandatory: false,
            label: 'Output variables',
            read_only: false,
            active: true,
            column_type: 'glide_var',
        }),
        performance_include: BooleanColumn({
            mandatory: false,
            label: 'Include for Performance Comparison',
            read_only: false,
            active: true,
            default: false,
        }),
        step_env: ReferenceColumn({
            mandatory: true,
            label: 'Step environment',
            read_only: false,
            active: true,
            default: '6c2bcea1870312009dccc9ded0e3ecca',
            referenceTable: 'sys_atf_step_env',
        }),
        step_execution_generator: GenericColumn({
            mandatory: false,
            label: 'Step execution script',
            read_only: false,
            active: true,
            default: 'javascript:new ATFVariablesUtil().getDefaultStepConfigScript();',
            column_type: 'script_plain',
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        template_reminder: TranslatedTextColumn({
            mandatory: true,
            label: 'Template reminder',
            read_only: false,
            active: true,
        }),
        type: ReferenceColumn({
            mandatory: true,
            label: 'Type',
            read_only: false,
            active: true,
            default:
                "javascript:var atf_step_db_object = new GlideRecord('sys_db_object'); atf_step_db_object.get('name', 'sys_atf_step'); atf_step_db_object.sys_id;",
            referenceTable: 'sys_db_object',
        }),
        wizard_redirect: StringColumn({
            mandatory: false,
            label: 'Wizard Redirect',
            read_only: false,
            active: true,
            maxLength: 255,
            dropdown: 'none',
        }),
    },
})
